    setEffReplaceTexture( speff, 2, 0 );  -- カード差し替え
    setEffReplaceTexture( speff, 5, 4 );  -- 技名テクスチャ差し替え

    -- ** 集中線 ** --
    local shuchusen = entryEffectLife( startFrame + 0, 906, 90, 0x100, -1, 0, 0, 0 );  -- 集中線
