    setEffMoveKey( startFrame + 0, housha, 0, 0 , 0 );
    setEffMoveKey( startFrame + 90, housha, 0, 0 , 0 );
    setEffScaleKey( startFrame + 0, housha, 1.0, 1.0 );
    setEffScaleKey( startFrame + 90, housha, 1.0, 1.0 );
